import React, { Component } from 'react';

class Kitchen extends Component {
  render() {
    return (
      <div style={{ padding: '20px' }}>
        <h3 style={{ color: '#4A2E2B', fontWeight: 'bold' }}>QUẢN LÝ BẾP & CHẾ BIẾN</h3>
        <p>Khu vực hiển thị danh sách món ăn cần chế biến cho đầu bếp...</p>
      </div>
    );
  }
}

export default Kitchen;
